using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using OnlineStore.Data;
using OnlineStore.ViewModels;
namespace OnlineStore.Controllers;
public class ProductsController(StoreContext db) : Controller { public async Task<IActionResult> Index(string? search, int? categoryId) { var q = db.Products.Include(p => p.Category).AsQueryable(); if (!string.IsNullOrWhiteSpace(search)) q = q.Where(p => p.Name.Contains(search) || p.Description.Contains(search) || p.Category!.Name.Contains(search)); if (categoryId.HasValue) q = q.Where(p => p.CategoryId == categoryId); var products = await q.ToListAsync(); var similar = new List<OnlineStore.Models.Product>(); if (!string.IsNullOrWhiteSpace(search) && products.Any()) { var categoryIds = products.Select(p => p.CategoryId).Distinct().ToList(); var productIds = products.Select(p => p.Id).ToList(); similar = await db.Products.Include(p => p.Category).Where(p => categoryIds.Contains(p.CategoryId) && !productIds.Contains(p.Id)).Take(6).ToListAsync(); } return View(new ProductsViewModel { Products = products, SimilarProducts = similar, Categories = await db.Categories.ToListAsync(), Search = search, CategoryId = categoryId }); } public async Task<IActionResult> Details(int? id) { if (id is null) return NotFound(); var product = await db.Products.Include(p => p.Category).FirstOrDefaultAsync(p => p.Id == id); return product is null ? NotFound() : View(product); } }
